#!/usr/bin/env python3
"""Regression: tab/workspace action naming is consistent in CLI + socket v2."""

import glob
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Dict, List

sys.path.insert(0, str(Path(__file__).parent))
from cmux import cmux, cmuxError


SOCKET_PATH = os.environ.get("CMUX_SOCKET", "/tmp/cmux-debug.sock")


def _must(cond: bool, msg: str) -> None:
    if not cond:
        raise cmuxError(msg)


def _find_cli_binary() -> str:
    env_cli = os.environ.get("CMUXTERM_CLI")
    if env_cli and os.path.isfile(env_cli) and os.access(env_cli, os.X_OK):
        return env_cli

    fixed = os.path.expanduser("~/Library/Developer/Xcode/DerivedData/cmux-tests-v2/Build/Products/Debug/cmux")
    if os.path.isfile(fixed) and os.access(fixed, os.X_OK):
        return fixed

    candidates = glob.glob(os.path.expanduser("~/Library/Developer/Xcode/DerivedData/**/Build/Products/Debug/cmux"), recursive=True)
    candidates += glob.glob("/tmp/cmux-*/Build/Products/Debug/cmux")
    candidates = [p for p in candidates if os.path.isfile(p) and os.access(p, os.X_OK)]
    if not candidates:
        raise cmuxError("Could not locate cmux CLI binary; set CMUXTERM_CLI")
    candidates.sort(key=lambda p: os.path.getmtime(p), reverse=True)
    return candidates[0]


def _run_cli(cli: str, args: List[str], json_output: bool) -> str:
    env = dict(os.environ)
    env.pop("CMUX_WORKSPACE_ID", None)
    env.pop("CMUX_SURFACE_ID", None)
    env.pop("CMUX_TAB_ID", None)

    cmd = [cli, "--socket", SOCKET_PATH]
    if json_output:
        cmd.append("--json")
    cmd.extend(args)

    proc = subprocess.run(cmd, capture_output=True, text=True, check=False, env=env)
    if proc.returncode != 0:
        merged = f"{proc.stdout}\n{proc.stderr}".strip()
        raise cmuxError(f"CLI failed ({' '.join(cmd)}): {merged}")
    return proc.stdout


def _run_cli_json(cli: str, args: List[str]) -> Dict:
    output = _run_cli(cli, args, json_output=True)
    try:
        return json.loads(output or "{}")
    except Exception as exc:  # noqa: BLE001
        raise cmuxError(f"Invalid JSON output for {' '.join(args)}: {output!r} ({exc})")


def _focused_surface_ref(c: cmux, workspace_id: str) -> str:
    current = c._call("surface.current", {"workspace_id": workspace_id}) or {}
    surface_ref = str(current.get("surface_ref") or "")
    if surface_ref.startswith("surface:"):
        return surface_ref

    listed = c._call("surface.list", {"workspace_id": workspace_id}) or {}
    rows = listed.get("surfaces") or []
    for row in rows:
        if bool(row.get("focused")):
            ref = str(row.get("ref") or "")
            if ref.startswith("surface:"):
                return ref
    for row in rows:
        ref = str(row.get("ref") or "")
        if ref.startswith("surface:"):
            return ref

    raise cmuxError(f"Unable to resolve focused surface ref in workspace {workspace_id}: {listed}")


def main() -> int:
    cli = _find_cli_binary()

    help_text = _run_cli(cli, ["tab-action", "--help"], json_output=False)
    _must("Target tab" in help_text, "tab-action --help should describe tab target naming")
    _must("tab:<n>" in help_text, "tab-action --help should mention tab:<n> refs")
    _must("--tab tab:" in help_text, "tab-action examples should use tab: refs")

    with cmux(SOCKET_PATH) as c:
        caps = c.capabilities() or {}
        methods = set(caps.get("methods") or [])
        for method in ["workspace.action", "tab.action", "surface.action"]:
            _must(method in methods, f"Missing method in capabilities: {method}")

        created = c._call("workspace.create", {}) or {}
        ws_id = str(created.get("workspace_id") or "")
        _must(bool(ws_id), f"workspace.create returned no workspace_id: {created}")
        ws_other = ""
        try:
            c._call("workspace.select", {"workspace_id": ws_id})

            surface_ref = _focused_surface_ref(c, ws_id)
            tab_ref = "tab:" + surface_ref.split(":", 1)[1]

            pin = _run_cli_json(cli, ["tab-action", "--workspace", ws_id, "--tab", tab_ref, "--action", "pin"])
            _must(str(pin.get("tab_ref") or "").startswith("tab:"), f"Expected tab_ref in tab-action payload: {pin}")
            _must(bool(pin.get("pinned")) is True, f"tab-action pin should report pinned=true: {pin}")

            unpin = _run_cli_json(cli, ["tab-action", "--workspace", ws_id, "--tab", tab_ref, "--action", "unpin"])
            _must(bool(unpin.get("pinned")) is False, f"tab-action unpin should report pinned=false: {unpin}")

            socket_tab = c._call("tab.action", {"workspace_id": ws_id, "tab_id": tab_ref, "action": "clear_name"}) or {}
            _must(str(socket_tab.get("tab_ref") or "").startswith("tab:"), f"Expected tab_ref in tab.action result: {socket_tab}")
            _must(str(socket_tab.get("workspace_id") or "") == ws_id, f"tab.action should target requested workspace: {socket_tab}")

            other_created = c._call("workspace.create", {}) or {}
            ws_other = str(other_created.get("workspace_id") or "")
            _must(bool(ws_other), f"workspace.create (second) returned no workspace_id: {other_created}")
            c._call("workspace.select", {"workspace_id": ws_other})
            ws_target_ref = ""
            ws_list = c._call("workspace.list", {}) or {}
            for row in ws_list.get("workspaces") or []:
                if str(row.get("id") or "") == ws_id:
                    ws_target_ref = str(row.get("ref") or "")
                    break

            # Regression: workspace-scoped tab-action without --tab should target that workspace,
            # not whichever tab is globally focused in another workspace.
            cli_scoped = _run_cli_json(cli, ["tab-action", "--workspace", ws_id, "--action", "mark-unread"])
            _must(str(cli_scoped.get("tab_ref") or "").startswith("tab:"), f"Expected tab_ref in scoped tab-action result: {cli_scoped}")
            got_scoped_workspace = str(cli_scoped.get("workspace_id") or cli_scoped.get("workspace_ref") or "")
            _must(
                got_scoped_workspace in {x for x in [ws_id, ws_target_ref] if x},
                f"workspace-scoped tab-action should resolve target workspace: {cli_scoped}",
            )

            # Regression: tab_id alone should resolve both tab manager + workspace, even when another workspace is selected.
            by_tab_only = c._call("tab.action", {"tab_id": tab_ref, "action": "mark_unread"}) or {}
            _must(str(by_tab_only.get("tab_ref") or "").startswith("tab:"), f"Expected tab_ref in tab_id-only result: {by_tab_only}")
            _must(str(by_tab_only.get("workspace_id") or "") == ws_id, f"tab_id-only action should resolve target workspace: {by_tab_only}")

            mark_read = c._call("tab.action", {"tab_id": tab_ref, "action": "mark_read"}) or {}
            _must(str(mark_read.get("tab_ref") or "").startswith("tab:"), f"Expected tab_ref in mark_read result: {mark_read}")
            _must(str(mark_read.get("workspace_id") or "") == ws_id, f"mark_read should resolve target workspace: {mark_read}")
        finally:
            if ws_other:
                try:
                    c.close_workspace(ws_other)
                except Exception:
                    pass
            try:
                c.close_workspace(ws_id)
            except Exception:
                pass

    print("PASS: tab/workspace naming stays consistent across tab-action CLI and socket APIs")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Regression tests for browser.open_split caller-relative pane reuse."""

import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from cmux import cmux, cmuxError


SOCKET_PATH = os.environ.get("CMUX_SOCKET", "/tmp/cmux-debug.sock")


def _must(cond: bool, msg: str) -> None:
    if not cond:
        raise cmuxError(msg)


def _surface_id(payload: dict) -> str:
    return str((payload or {}).get("surface_id") or "")


def _pane_id(payload: dict) -> str:
    return str((payload or {}).get("pane_id") or "")


def _pane_count(c: cmux, workspace_id: str) -> int:
    panes_payload = c._call("pane.list", {"workspace_id": workspace_id}) or {}
    panes = panes_payload.get("panes") or []
    return len(panes)


def _pane_for_surface(c: cmux, workspace_id: str, surface_id: str) -> str:
    payload = c._call("surface.list", {"workspace_id": workspace_id}) or {}
    for row in payload.get("surfaces") or []:
        if str(row.get("id") or "") == surface_id:
            pane = str(row.get("pane_id") or "")
            if pane:
                return pane
    raise cmuxError(f"Surface {surface_id} not found in workspace {workspace_id}: {payload}")


def main() -> int:
    with cmux(SOCKET_PATH) as c:
        created = c._call("workspace.create", {}) or {}
        workspace_id = str(created.get("workspace_id") or "")
        _must(bool(workspace_id), f"workspace.create returned no workspace_id: {created}")
        c._call("workspace.select", {"workspace_id": workspace_id})

        current = c._call("surface.current", {"workspace_id": workspace_id}) or {}
        left_surface = str(current.get("surface_id") or "")
        _must(bool(left_surface), f"surface.current returned no surface_id: {current}")

        right = c._call(
            "surface.split",
            {"workspace_id": workspace_id, "surface_id": left_surface, "direction": "right"},
        ) or {}
        right_surface = _surface_id(right)
        _must(bool(right_surface), f"surface.split right returned no surface_id: {right}")

        right_down = c._call(
            "surface.split",
            {"workspace_id": workspace_id, "surface_id": right_surface, "direction": "down"},
        ) or {}
        right_bottom_surface = _surface_id(right_down)
        _must(bool(right_bottom_surface), f"surface.split right/down returned no surface_id: {right_down}")

        left_down = c._call(
            "surface.split",
            {"workspace_id": workspace_id, "surface_id": left_surface, "direction": "down"},
        ) or {}
        left_bottom_surface = _surface_id(left_down)
        _must(bool(left_bottom_surface), f"surface.split left/down returned no surface_id: {left_down}")

        right_top_pane = _pane_for_surface(c, workspace_id, right_surface)
        right_bottom_pane = _pane_for_surface(c, workspace_id, right_bottom_surface)

        base_panes = _pane_count(c, workspace_id)

        open_from_left_top = c._call(
            "browser.open_split",
            {"workspace_id": workspace_id, "surface_id": left_surface, "url": "about:blank"},
        ) or {}
        _must(bool(open_from_left_top.get("created_split")) is False, f"Expected pane reuse from left-top: {open_from_left_top}")
        _must(
            str(open_from_left_top.get("target_pane_id") or "") == right_top_pane,
            f"Expected left-top to reuse top-right pane ({right_top_pane}): {open_from_left_top}",
        )
        _must(_pane_count(c, workspace_id) == base_panes, "Pane count changed during left-top reuse")

        open_from_left_bottom = c._call(
            "browser.open_split",
            {"workspace_id": workspace_id, "surface_id": left_bottom_surface, "url": "about:blank"},
        ) or {}
        _must(bool(open_from_left_bottom.get("created_split")) is False, f"Expected pane reuse from left-bottom: {open_from_left_bottom}")
        _must(
            str(open_from_left_bottom.get("target_pane_id") or "") == right_bottom_pane,
            f"Expected left-bottom to reuse bottom-right pane ({right_bottom_pane}): {open_from_left_bottom}",
        )
        _must(_pane_count(c, workspace_id) == base_panes, "Pane count changed during left-bottom reuse")

        before_right_open = _pane_count(c, workspace_id)
        open_from_right = c._call(
            "browser.open_split",
            {"workspace_id": workspace_id, "surface_id": right_bottom_surface, "url": "about:blank"},
        ) or {}
        _must(bool(open_from_right.get("created_split")) is True, f"Expected new split from right-most pane: {open_from_right}")
        _must(
            _pane_count(c, workspace_id) == before_right_open + 1,
            f"Expected pane count +1 after right-most open_split: before={before_right_open} after={_pane_count(c, workspace_id)}",
        )

    print("PASS: browser.open_split reuses nearest right pane and only splits from right-most callers")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""v2 regression: browser DevTools stays open after a single toggle."""

import os
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from cmux import cmux, cmuxError


SOCKET_PATH = os.environ.get("CMUX_SOCKET", "/tmp/cmux-debug.sock")


def _must(cond: bool, msg: str) -> None:
    if not cond:
        raise cmuxError(msg)


def _wait_until(pred, timeout_s: float, label: str) -> None:
    deadline = time.time() + timeout_s
    last_exc = None
    while time.time() < deadline:
        try:
            if pred():
                return
        except Exception as exc:  # noqa: BLE001
            last_exc = exc
        time.sleep(0.05)
    if last_exc is not None:
        raise cmuxError(f"Timed out waiting for {label}: {last_exc}")
    raise cmuxError(f"Timed out waiting for {label}")


def _surface_row(c: cmux, workspace_id: str, surface_id: str) -> dict:
    payload = c._call("surface.list", {"workspace_id": workspace_id}) or {}
    for row in payload.get("surfaces") or []:
        if str(row.get("id") or "") == surface_id:
            return row
    raise cmuxError(f"surface.list missing surface {surface_id} in workspace {workspace_id}: {payload}")


def _devtools_visible(c: cmux, workspace_id: str, surface_id: str) -> bool:
    row = _surface_row(c, workspace_id, surface_id)
    return bool(row.get("developer_tools_visible"))


def _focus_browser_webview(c: cmux, surface_id: str, timeout_s: float = 2.0) -> None:
    deadline = time.time() + timeout_s
    last_exc = None
    while time.time() < deadline:
        try:
            c.focus_surface(surface_id)
            c.focus_webview(surface_id)
            if c.is_webview_focused(surface_id):
                return
        except Exception as exc:  # noqa: BLE001
            last_exc = exc
        time.sleep(0.05)
    raise cmuxError(f"Timed out waiting for browser webview focus: {last_exc}")


def main() -> int:
    with cmux(SOCKET_PATH) as c:
        workspace_id = c.new_workspace()
        try:
            c.select_workspace(workspace_id)
            time.sleep(0.3)

            surface_id = c.new_surface(panel_type="browser", url="https://example.com")
            _wait_until(
                lambda: _surface_row(c, workspace_id, surface_id).get("type") == "browser",
                timeout_s=5.0,
                label="browser surface in surface.list",
            )
            _focus_browser_webview(c, surface_id, timeout_s=3.0)

            _must(
                _devtools_visible(c, workspace_id, surface_id) is False,
                "Expected DevTools to start closed",
            )

            c.simulate_shortcut("cmd+opt+i")

            _wait_until(
                lambda: _devtools_visible(c, workspace_id, surface_id),
                timeout_s=3.0,
                label="DevTools visible after toggle",
            )

            deadline = time.time() + 1.5
            while time.time() < deadline:
                _must(
                    _devtools_visible(c, workspace_id, surface_id) is True,
                    "DevTools reopened/closed unexpectedly after initial open",
                )
                time.sleep(0.05)
        finally:
            try:
                c.close_workspace(workspace_id)
            except Exception:
                pass

    print("PASS: browser DevTools stays open after a single toggle")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
